CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discord_id text UNIQUE NOT NULL,username text NOT NULL,email text UNIQUE NOT NULL,coins bigint NOT NULL DEFAULT 0,blacklisted boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS servers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_id text UNIQUE NOT NULL,name text NOT NULL,type text NOT NULL,status text NOT NULL DEFAULT 'provisioning',owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,ptero_server_id integer,ptero_identifier text UNIQUE,node_id integer,egg_id integer,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS server_access(server_id uuid NOT NULL REFERENCES servers(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(server_id,user_id));
CREATE TABLE IF NOT EXISTS coin_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,actor_id uuid REFERENCES users(id),amount bigint NOT NULL,type text NOT NULL,reference text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id uuid REFERENCES users(id),action text NOT NULL,target_type text,target_id text,success boolean NOT NULL DEFAULT true,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),referrer_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,referred_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,rewarded boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rewards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,external_id text,amount bigint NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,external_id));
CREATE INDEX IF NOT EXISTS servers_owner_idx ON servers(owner_id); CREATE INDEX IF NOT EXISTS ledger_user_idx ON coin_ledger(user_id,created_at DESC); CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at DESC);